mappages["asharden1"].onload = function(mapref) {

  if ((gamestate.getMode() !== "loadgame") && (!DU.gameflags.getFlag("editor"))) {

    let asharden;
    let npcs = mapref.npcs.getAll();
    for (let i=0;i<npcs.length;i++) {
      if (npcs[i].getNPCName() === "Asharden") { asharden = npcs[i]; }
    }

    if (DU.gameflags.getFlag("ashardenprimer") && !DU.gameflags.getFlag("planargate2")) {
      let a3 = maps.getMap("asharden3");
      MoveBetweenMaps(asharden,mapref,a3,26,18);

      if (!DU.gameflags.getFlag("planargate")) {
        let starttime = DU.gameflags.getFlag("ashardenprimer");
        let timepassed = DUTime.getGameClock() - parseFloat(starttime);

        if (timepassed > 24) {
          let gate = localFactory.createTile("PlanarGateInactive");
          a3.placeThing(27,18,gate);
          DU.gameflags.setFlag("planargate",1);
        } else if (timepassed > 12) {
          let gate = localFactory.createTile("PlanarGateIncomplete");
          a3.placeThing(27,18,gate);
          gate.spritexoffset += 32;
        } else if (timepassed > 6) {
          let gate = localFactory.createTile("PlanarGateIncomplete");
          a3.placeThing(27,18,gate);
        }
      }
    }


    let doorloc = mapref.getTile(25,21);
    let door = doorloc.getTopFeature();
    if (DU.gameflags.getFlag("ash_password")) {  
    // gave password previously, unlock the door
      mapref.deleteThing(door);
      var newdoor = localFactory.createTile("Door");
      mapref.placeThing(25,21,newdoor);
    } 
    if (DU.gameflags.getFlag("ash_get_book")) {
      DU.gameflags.deleteFlag("ash_get_book");
      DU.gameflags.setFlag("ash_has_book",1);
    }
    
    let place_ivan = 0;
    if ((DU.gameflags.getFlag("ivan_lastvisitchecktime") && !IsNight() && ((DUTime.getGameClock() - DU.gameflags.getFlag("ivan_lastvisitchecktime")) > 20)) || (!DU.gameflags.getFlag("ivan_lastvisitchecktime"))) {
      // decide if placing Ivan
      if (Dice.roll("1d4") === 1) {
        place_ivan=1;
      }
    } else {
      // use last value for Ivan's presence
      if (DU.gameflags.getFlag("ivan_lastvisit") === 1) {
        place_ivan = 1;
      }
    }
    
    DU.gameflags.setFlag("ivan_lastvisit",place_ivan);
    DU.gameflags.setFlag("ivan_lastvisitchecktime",DUTime.getGameClock());
    
    if (place_ivan) {
      // place him at 22,19
      // place walkon at 25,20 to start dialog
      // WORKING HERE
    } else {
      let ivan = FindNPCByName("Ivan",mapref);
      mapref.deleteThing(ivan);
      DUTime.removeEntityFrom(ivan);
    }
  }
}

